mkfn!{
    compute_locs_introspect!();
    pub (super) fn compute_locs (matcher : & [TokenTree]) -> Vec < MatcherLoc > { fn inner (tts : & [TokenTree] , locs : & mut Vec < MatcherLoc > , next_metavar : & mut usize , seq_depth : usize ,) { for tt in tts { match tt { TokenTree :: Token (token) => { locs . push (MatcherLoc :: Token { token : * token }) ; } TokenTree :: Delimited (span , _ , delimited) => { let open_token = Token :: new (delimited . delim . as_open_token_kind () , span . open) ; let close_token = Token :: new (delimited . delim . as_close_token_kind () , span . close) ; locs . push (MatcherLoc :: Delimited) ; locs . push (MatcherLoc :: Token { token : open_token }) ; inner (& delimited . tts , locs , next_metavar , seq_depth) ; locs . push (MatcherLoc :: Token { token : close_token }) ; } TokenTree :: Sequence (_ , seq) => { let dummy = MatcherLoc :: Eof ; locs . push (dummy) ; let next_metavar_orig = * next_metavar ; let op = seq . kleene . op ; let idx_first = locs . len () ; let idx_seq = idx_first - 1 ; inner (& seq . tts , locs , next_metavar , seq_depth + 1) ; if let Some (separator) = & seq . separator { locs . push (MatcherLoc :: SequenceSep { separator : separator . clone () }) ; locs . push (MatcherLoc :: SequenceKleeneOpAfterSep { idx_first }) ; } else { locs . push (MatcherLoc :: SequenceKleeneOpNoSep { op , idx_first }) ; } locs [idx_seq] = MatcherLoc :: Sequence { op , num_metavar_decls : seq . num_captures , idx_first_after : locs . len () , next_metavar : next_metavar_orig , seq_depth , } ; } & TokenTree :: MetaVarDecl { span , name : bind , kind } => { locs . push (MatcherLoc :: MetaVarDecl { span , bind , kind , next_metavar : * next_metavar , seq_depth , }) ; * next_metavar += 1 ; } TokenTree :: MetaVar (..) | TokenTree :: MetaVarExpr (..) => unreachable ! () , } } } let mut locs = vec ! [] ; let mut next_metavar = 0 ; inner (matcher , & mut locs , & mut next_metavar , 0) ; locs . push (MatcherLoc :: Eof) ; locs }
}
mkitem!{mkstruct!{# [doc = " A single matcher position, representing the state of matching."] # [derive (Debug)] struct MatcherPos { # [doc = " The index into `TtParser::locs`, which represents the \"dot\"."] idx : usize , # [doc = " The matches made against metavar decls so far. On a successful match, this vector ends up"] # [doc = " with one element per metavar decl in the matcher. Each element records token trees matched"] # [doc = " against the relevant metavar by the black box parser. An element will be a `MatchedSeq` if"] # [doc = " the corresponding metavar decl is within a sequence."] # [doc = ""] # [doc = " It is critical to performance that this is an `Rc`, because it gets cloned frequently when"] # [doc = " processing sequences. Mostly for sequence-ending possibilities that must be tried but end"] # [doc = " up failing."] matches : Rc < Vec < NamedMatch > > , }}}
mkitem!{# [cfg (target_pointer_width = "64")] rustc_data_structures :: static_assert_size ! (MatcherPos , 16) ;}
mkitem!{mkimpl!{impl MatcherPos { # [doc = " Adds `m` as a named match for the `metavar_idx`-th metavar. There are only two call sites,"] # [doc = " and both are hot enough to be always worth inlining."] # [inline (always)] fn push_match (& mut self , metavar_idx : usize , seq_depth : usize , m : NamedMatch) { let matches = Rc :: make_mut (& mut self . matches) ; match seq_depth { 0 => { assert_eq ! (metavar_idx , matches . len ()) ; matches . push (m) ; } _ => { let mut curr = & mut matches [metavar_idx] ; for _ in 0 .. seq_depth - 1 { match curr { MatchedSeq (seq) => curr = seq . last_mut () . unwrap () , _ => unreachable ! () , } } match curr { MatchedSeq (seq) => seq . push (m) , _ => unreachable ! () , } } } } }}}
mkitem!{mkenum!{enum EofMatcherPositions { None , One (MatcherPos) , Multiple , }}}
mkitem!{mkenum!{# [doc = " Represents the possible results of an attempted parse."] # [derive (Debug)] pub (crate) enum ParseResult < T , F > { # [doc = " Parsed successfully."] Success (T) , # [doc = " Arm failed to match. If the second parameter is `token::Eof`, it indicates an unexpected"] # [doc = " end of macro invocation. Otherwise, it indicates that no rules expected the given token."] # [doc = " The usize is the approximate position of the token in the input token stream."] Failure (F) , # [doc = " Fatal error (malformed macro?). Abort compilation."] Error (rustc_span :: Span , String) , ErrorReported (ErrorGuaranteed) , }}}
mkitem!{# [doc = " A `ParseResult` where the `Success` variant contains a mapping of"] # [doc = " `MacroRulesNormalizedIdent`s to `NamedMatch`es. This represents the mapping"] # [doc = " of metavars to the token trees they bind to."] pub (crate) type NamedParseResult < F > = ParseResult < NamedMatches , F > ;}
mkitem!{# [doc = " Contains a mapping of `MacroRulesNormalizedIdent`s to `NamedMatch`es."] # [doc = " This represents the mapping of metavars to the token trees they bind to."] pub (crate) type NamedMatches = FxHashMap < MacroRulesNormalizedIdent , NamedMatch > ;}

