mkfn!{
    token_name_eq_introspect!();
    # [doc = " Performs a token equality check, ignoring syntax context (that is, an unhygienic comparison)"] fn token_name_eq (t1 : & Token , t2 : & Token) -> bool { if let (Some ((ident1 , is_raw1)) , Some ((ident2 , is_raw2))) = (t1 . ident () , t2 . ident ()) { ident1 . name == ident2 . name && is_raw1 == is_raw2 } else if let (Some ((ident1 , is_raw1)) , Some ((ident2 , is_raw2))) = (t1 . lifetime () , t2 . lifetime ()) { ident1 . name == ident2 . name && is_raw1 == is_raw2 } else { match (t1 . kind , t2 . kind) { (TokenKind :: OpenInvisible (_) | TokenKind :: CloseInvisible (_) , _) | (_ , TokenKind :: OpenInvisible (_) | TokenKind :: CloseInvisible (_)) => false , (a , b) => a == b , } } }
}
mkitem!{mkstruct!{pub (crate) struct TtParser { macro_name : Ident , # [doc = " The set of current mps to be processed. This should be empty by the end of a successful"] # [doc = " execution of `parse_tt_inner`."] cur_mps : Vec < MatcherPos > , # [doc = " The set of newly generated mps. These are used to replenish `cur_mps` in the function"] # [doc = " `parse_tt`."] next_mps : Vec < MatcherPos > , # [doc = " The set of mps that are waiting for the black-box parser."] bb_mps : Vec < MatcherPos > , # [doc = " Pre-allocate an empty match array, so it can be cloned cheaply for macros with many rules"] # [doc = " that have no metavars."] empty_matches : Rc < Vec < NamedMatch > > , }}}
mkitem!{mkimpl!{impl TtParser { pub (super) fn new (macro_name : Ident) -> TtParser { TtParser { macro_name , cur_mps : vec ! [] , next_mps : vec ! [] , bb_mps : vec ! [] , empty_matches : Rc :: new (vec ! []) , } } pub (super) fn has_no_remaining_items_for_step (& self) -> bool { self . cur_mps . is_empty () } # [doc = " Process the matcher positions of `cur_mps` until it is empty. In the process, this will"] # [doc = " produce more mps in `next_mps` and `bb_mps`."] # [doc = ""] # [doc = " # Returns"] # [doc = ""] # [doc = " `Some(result)` if everything is finished, `None` otherwise. Note that matches are kept"] # [doc = " track of through the mps generated."] fn parse_tt_inner < 'matcher , T : Tracker < 'matcher > > (& mut self , matcher : & 'matcher [MatcherLoc] , token : & Token , approx_position : u32 , track : & mut T ,) -> Option < NamedParseResult < T :: Failure > > { let mut eof_mps = EofMatcherPositions :: None ; while let Some (mut mp) = self . cur_mps . pop () { let matcher_loc = & matcher [mp . idx] ; track . before_match_loc (self , matcher_loc) ; match matcher_loc { MatcherLoc :: Token { token : t } => { if matches ! (t , Token { kind : DocComment (..) , .. }) { mp . idx += 1 ; self . cur_mps . push (mp) ; } else if token_name_eq (t , token) { mp . idx += 1 ; self . next_mps . push (mp) ; } } MatcherLoc :: Delimited => { mp . idx += 1 ; self . cur_mps . push (mp) ; } & MatcherLoc :: Sequence { op , num_metavar_decls , idx_first_after , next_metavar , seq_depth , } => { for metavar_idx in next_metavar .. next_metavar + num_metavar_decls { mp . push_match (metavar_idx , seq_depth , MatchedSeq (vec ! [])) ; } if matches ! (op , KleeneOp :: ZeroOrMore | KleeneOp :: ZeroOrOne) { self . cur_mps . push (MatcherPos { idx : idx_first_after , matches : Rc :: clone (& mp . matches) , }) ; } mp . idx += 1 ; self . cur_mps . push (mp) ; } & MatcherLoc :: SequenceKleeneOpNoSep { op , idx_first } => { let ending_mp = MatcherPos { idx : mp . idx + 1 , matches : Rc :: clone (& mp . matches) , } ; self . cur_mps . push (ending_mp) ; if op != KleeneOp :: ZeroOrOne { mp . idx = idx_first ; self . cur_mps . push (mp) ; } } MatcherLoc :: SequenceSep { separator } => { let ending_mp = MatcherPos { idx : mp . idx + 2 , matches : Rc :: clone (& mp . matches) , } ; self . cur_mps . push (ending_mp) ; if token_name_eq (token , separator) { mp . idx += 1 ; self . next_mps . push (mp) ; } } & MatcherLoc :: SequenceKleeneOpAfterSep { idx_first } => { mp . idx = idx_first ; self . cur_mps . push (mp) ; } & MatcherLoc :: MetaVarDecl { kind , .. } => { if Parser :: nonterminal_may_begin_with (kind , token) { self . bb_mps . push (mp) ; } } MatcherLoc :: Eof => { debug_assert_eq ! (mp . idx , matcher . len () - 1) ; if * token == token :: Eof { eof_mps = match eof_mps { EofMatcherPositions :: None => EofMatcherPositions :: One (mp) , EofMatcherPositions :: One (_) | EofMatcherPositions :: Multiple => { EofMatcherPositions :: Multiple } } } } } } if * token == token :: Eof { Some (match eof_mps { EofMatcherPositions :: One (mut eof_mp) => { Rc :: make_mut (& mut eof_mp . matches) ; let matches = Rc :: try_unwrap (eof_mp . matches) . unwrap () . into_iter () ; self . nameize (matcher , matches) } EofMatcherPositions :: Multiple => { Error (token . span , "ambiguity: multiple successful parses" . to_string ()) } EofMatcherPositions :: None => Failure (T :: build_failure (Token :: new (token :: Eof , if token . span . is_dummy () { token . span } else { token . span . shrink_to_hi () } ,) , approx_position , "missing tokens in macro arguments" ,)) , }) } else { None } } # [doc = " Match the token stream from `parser` against `matcher`."] pub (super) fn parse_tt < 'matcher , T : Tracker < 'matcher > > (& mut self , parser : & mut Cow < '_ , Parser < '_ > > , matcher : & 'matcher [MatcherLoc] , track : & mut T ,) -> NamedParseResult < T :: Failure > { self . cur_mps . clear () ; self . cur_mps . push (MatcherPos { idx : 0 , matches : Rc :: clone (& self . empty_matches) }) ; loop { self . next_mps . clear () ; self . bb_mps . clear () ; let res = self . parse_tt_inner (matcher , & parser . token , parser . approx_token_stream_pos () , track ,) ; if let Some (res) = res { return res ; } assert ! (self . cur_mps . is_empty ()) ; match (self . next_mps . len () , self . bb_mps . len ()) { (0 , 0) => { return Failure (T :: build_failure (parser . token , parser . approx_token_stream_pos () , "no rules expected this token in macro call" ,)) ; } (_ , 0) => { self . cur_mps . append (& mut self . next_mps) ; parser . to_mut () . bump () ; } (0 , 1) => { let mut mp = self . bb_mps . pop () . unwrap () ; let loc = & matcher [mp . idx] ; if let & MatcherLoc :: MetaVarDecl { span , kind , next_metavar , seq_depth , .. } = loc { let nt = match parser . to_mut () . parse_nonterminal (kind) { Err (err) => { let guarantee = err . with_span_label (span , format ! ("while parsing argument for this `{kind}` macro fragment") ,) . emit () ; return ErrorReported (guarantee) ; } Ok (nt) => nt , } ; mp . push_match (next_metavar , seq_depth , MatchedSingle (nt)) ; mp . idx += 1 ; } else { unreachable ! () } self . cur_mps . push (mp) ; } (_ , _) => { return self . ambiguity_error (matcher , parser . token . span) ; } } assert ! (! self . cur_mps . is_empty ()) ; } } fn ambiguity_error < F > (& self , matcher : & [MatcherLoc] , token_span : rustc_span :: Span ,) -> NamedParseResult < F > { let nts = self . bb_mps . iter () . map (| mp | match & matcher [mp . idx] { MatcherLoc :: MetaVarDecl { bind , kind , .. } => { format ! ("{kind} ('{bind}')") } _ => unreachable ! () , }) . collect :: < Vec < String > > () . join (" or ") ; Error (token_span , format ! ("local ambiguity when calling macro `{}`: multiple parsing options: {}" , self . macro_name , match self . next_mps . len () { 0 => format ! ("built-in NTs {nts}.") , n => format ! ("built-in NTs {nts} or {n} other option{s}." , s = pluralize ! (n)) , }) ,) } fn nameize < I : Iterator < Item = NamedMatch > , F > (& self , matcher : & [MatcherLoc] , mut res : I ,) -> NamedParseResult < F > { let mut ret_val = FxHashMap :: default () ; for loc in matcher { if let & MatcherLoc :: MetaVarDecl { span , bind , .. } = loc { match ret_val . entry (MacroRulesNormalizedIdent :: new (bind)) { Vacant (spot) => spot . insert (res . next () . unwrap ()) , Occupied (..) => { return Error (span , format ! ("duplicated bind name: {bind}")) ; } } ; } } Success (ret_val) } }}}